//! Zartex core: the chunk container, the mission model, the Lua mission API and the Lua exports, and the reader of the
//! Parallel Lines city models. Each `pub mod` below is one part of the crate, and each part describes itself in its own
//! header. This file only declares the modules. It is used by the zartex-app crate and by the tests in tests/.
/// Constants of the Lua mission API, set as globals by `register_constants`. Generated by tools_gen_api.py.
pub mod api_consts;
/// Driver: Parallel Lines Lua environment: PACKAGE, INITMISSION and the DPL-only creators.
pub mod api_dpl;
/// Corrections for API methods that the generator translates wrongly.
pub mod api_fix;
/// Generated Lua API methods of LuaMissionScript (generated by tools_gen_api.py; do not edit).
pub mod api_gen;
/// Hand-ported parts of the Lua API that the generator cannot translate safely.
pub mod api_manual;
/// Lua API, part a: the actor creators of LuaMissionScript (Driv3r).
pub mod api_part_a;
/// Lua API, part b: methods such as CreateActorSetting, CreateWireCollection, GetActorById and SetActorUID.
pub mod api_part_b;
/// Lua API, part c: character controls and their wrappers, fades, bomb car, point checks, audio, character drive AI and clocks.
pub mod api_part_c;
/// Little-endian binary reader and writer, with the semantics of .NET streams.
pub mod binio;
/// The chunk container: packages, buffers and the file chunker (port of DSCript.Spooling).
pub mod chunk;
/// Driv3r Lua to .mpc compilation, and the Lua environment with the MISSION global.
pub mod compile;
/// Driver: Parallel Lines mission package (.sp), built from scratch.
pub mod dpl;
/// Logic data of a mission: string collection, sound banks, wires, actor sets and node definitions, with byte-level load and save.
pub mod logic;
/// Lua glue: argument conversion and the userdata types that scripts see (Actor, Node, CollectionOfWires, MissionSummary).
pub mod luaapi;
/// Lossless Lua export of a mission, and the MISSION.Raw* calls that read it back.
pub mod luaraw;
/// Table of the creator functions of the Lua API (generated by tools_gen_creators.py).
pub mod creators;
/// Readable Lua export: a mission written as calls of the mission API.
pub mod readable;
/// Mission-level resources: summary, instance data, the exported mission and the mission script file.
pub mod mission;
/// Node type name tables for logic and actor nodes, and a lookup function.
pub mod nodenames;
/// The objects of an exported mission (vehicles, characters, areas, paths and other object types).
pub mod objects;
/// Parallel Lines city model reader: packages, textures, tiles, props, interiors and roads.
pub mod plmodel;
/// Runtime state of a Lua mission script; the Lua API changes this state.
pub mod script;
